<?php
require_once __DIR__ . '/../includes/bootstrap.php'; header('Content-Type: application/json; charset=utf-8'); header('X-Content-Type-Options: nosniff');
function respond(int $code,array $data): never { http_response_code($code); echo json_encode($data,JSON_UNESCAPED_UNICODE); exit; }
if(!is_logged_in()) respond(401,['success'=>false,'message'=>'Sign in required.']); if(!is_admin()) respond(403,['success'=>false,'message'=>'Administrator access required.']);
$method=$_SERVER['REQUEST_METHOD'];
try{$conn=db(); if($method==='GET'){$q='%'.trim((string)($_GET['q']??'')).'%';$stmt=$conn->prepare('SELECT id,full_name,email,mobile,course,year_of_study,created_at FROM students WHERE full_name LIKE ? OR email LIKE ? OR mobile LIKE ? ORDER BY created_at DESC LIMIT 200');$stmt->bind_param('sss',$q,$q,$q);$stmt->execute();respond(200,['success'=>true,'data'=>$stmt->get_result()->fetch_all(MYSQLI_ASSOC)]);} if(!hash_equals(csrf_token(),(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))respond(419,['success'=>false,'message'=>'Security token invalid.']);$data=json_decode((string)file_get_contents('php://input'),true)??[];$id=(int)($data['id']??0);if($method==='DELETE'){$stmt=$conn->prepare('DELETE FROM students WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();respond(200,['success'=>true,'message'=>'Student record deleted.']);} if($method==='POST'||$method==='PUT'){$name=trim((string)($data['full_name']??''));$email=trim((string)($data['email']??''));$mobile=trim((string)($data['mobile']??''));$course=trim((string)($data['course']??''));$year=(int)($data['year_of_study']??0);if(!preg_match("/^[\\p{L}][\\p{L} .'-]{1,79}$/u",$name)||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[6-9][0-9]{9}$/',$mobile)||$course===''||$year<1||$year>4)respond(422,['success'=>false,'message'=>'Please provide valid student details.']);if($method==='PUT'){$stmt=$conn->prepare('UPDATE students SET full_name=?,email=?,mobile=?,course=?,year_of_study=? WHERE id=?');$stmt->bind_param('ssssii',$name,$email,$mobile,$course,$year,$id);$stmt->execute();respond(200,['success'=>true,'message'=>'Student updated.']);}$stmt=$conn->prepare('INSERT INTO students (full_name,email,mobile,course,year_of_study) VALUES (?,?,?,?,?)');$stmt->bind_param('ssssi',$name,$email,$mobile,$course,$year);$stmt->execute();respond(201,['success'=>true,'message'=>'Student created.','id'=>$conn->insert_id]);}respond(405,['success'=>false,'message'=>'Method not allowed.']);}catch(Throwable $ex){error_log('Students API: '.$ex->getMessage());respond(500,['success'=>false,'message'=>'The student request could not be completed.']);}
